import java.util.*;
import java.io.*;

public class Main {
    static int[] clusterSizes(int[] signature) {
        // Write your solution here
        int[] ans = new int[signature.length];
        Arrays.fill(ans, 1);
        return ans;
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        int[] signature = new int[n];
        for (int i = 0; i < n; i++) {
            in.nextToken();
            signature[i] = (int) in.nval;
        }
        int[] ans = clusterSizes(signature);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < ans.length; i++) sb.append(ans[i]).append(i + 1 < ans.length ? " " : "\n");
        System.out.print(sb);
    }
}
